(9, 1, 34, 'CINEMATOGRAPHY', false, 'George Barnes', NULL, NULL, NULL),
(10, 1, 34, 'CINEMATOGRAPHY', true, 'Charles Rosher, Karl Struss', NULL, 'NOTE: For this awards year, awards were presented in the name of the individual and could honor work on one or more films. Charles Rosher and Karl Struss were both honored for cinematography on this film. It is considered a single nomination for the film.', NULL),
