(426, 8, 18, 'WRITING (Screenplay)', false, 'Screenplay by Waldemar Young, John L. Balderston, Achmed Abdullah; Adaptation by Grover Jones, William Slavens McNutt', NULL, NULL, NULL),
(427, 8, 18, 'WRITING (Screenplay)', false, 'Talbot Jennings, Jules Furthman, Carey Wilson', NULL, 'came in 2nd', NULL),
(428, 8, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To David Wark Griffith, for his distinguished creative achievements as director and producer and his invaluable initiative and lasting contributions to the progress of the motion picture arts.'),
(429, 8, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Film', NULL, 'To AGFA ANSCO CORPORATION for their development of the Agfa infra-red film.'),
(430, 8, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Lenses and Filters', NULL, 'To EASTMAN KODAK COMPANY for their development of the Eastman Pola-Screen.'),
(431, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To METRO-GOLDWYN-MAYER STUDIO for the development of anti-directional negative and positive development by means of jet turbulation, and the application of the method to all negative and print processing of the entire product of a major producing company.'),
(432, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To WILLIAM A. MUELLER of Warner Bros.-First National Studio Sound Department for his method of dubbing, in which the level of the dialogue automatically controls the level of the accompanying music and sound effects.'),
(433, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To MOLE-RICHARDSON COMPANY for their development of the \"Solar-spot\" spot lamps.'),
(434, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To DOUGLAS SHEARER and METRO-GOLDWYN-MAYER STUDIO SOUND DEPARTMENT for their automatic control system for cameras and sound recording machines and auxiliary stage equipment.'),
(435, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To ELECTRICAL RESEARCH PRODUCTS, INC. for their study and development of equipment to analyze and measure flutter resulting from the travel of the film through the mechanisms used in the recording and reproduction of sound.'),
(436, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To PARAMOUNT PRODUCTIONS, INC. for the design and construction of the Paramount transparency air turbine developing machine.'),
(437, 8, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To NATHAN LEVINSON, Director of Sound Recording for Warner Bros.-First National Studio, for the method of intercutting variable density and variable area sound tracks to secure an increase in the effective volume range of sound recorded for motion pictures.'),
