insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(961, 12, 18, 'WRITING (Screenplay)', false, 'Sidney Buchman', NULL, NULL, NULL),
(962, 12, 18, 'WRITING (Screenplay)', false, 'Charles Brackett, Billy Wilder, Walter Reisch', NULL, NULL, NULL),
(963, 12, 18, 'WRITING (Screenplay)', false, 'Charles MacArthur, Ben Hecht', NULL, NULL, NULL),
(964, 12, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Douglas Fairbanks (Commemorative Award) - recognizing the unique and outstanding contribution of Douglas Fairbanks, first President of the Academy, to the international development of the motion picture.'),
(965, 12, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To The Motion Picture Relief Fund - acknowledging the outstanding services to the industry during the past year of the Motion Picture Relief Fund and its progressive leadership. Presented to Jean Hersholt, President; Ralph Morgan, Chairman of the Executive Committee; Ralph Block, First Vice-President; and Conrad Nagel.'),
(966, 12, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Judy Garland for her outstanding performance as a screen juvenile during the past year.'),
(967, 12, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To William Cameron Menzies for outstanding achievement in the use of color for the enhancement of dramatic mood in the production of Gone with the Wind.'),
(968, 12, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To the Technicolor Company for its contributions in successfully bringing three-color feature production to the screen.'),
(969, 12, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'David O. Selznick', NULL, NULL, NULL),
(970, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To GEORGE ANDERSON of Warner Bros. Studio for an improved positive head for sun arcs.'),
(971, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Camera Cranes', NULL, 'To JOHN ARNOLD of Metro-Goldwyn-Mayer Studio for the M-G-M mobile camera crane.'),
(972, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To THOMAS T. MOULTON, FRED ALBIN and the SOUND DEPARTMENT OF THE SAMUEL GOLDWYN STUDIO for the origination and application of the Delta db test to sound recording in motion pictures.'),
(973, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To FARCIOT EDOUART, JOSEPH E. ROBBINS, WILLIAM RUDOLPH and PARAMOUNT PICTURES, INC. for the design and construction of a quiet portable treadmill.'),
(974, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To EMERY HUSE and RALPH B. ATKINSON of the Eastman Kodak Company for their specifications for chemical analysis of photographic developers and fixing baths.'),
(975, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To HAROLD NYE of Warner Bros. Studio for a miniature incandescent spot lamp.'),
(976, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To A. J. TONDREAU of Warner Bros. Studio for the design and manufacture of an improved sound track printer.'),
(977, 12, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'For important contributions in cooperative development of new improved Process Projection Equipment: F. R. ABBOTT, HALLER BELT, ALAN COOK and the BAUSCH & LOMB OPTICAL COMPANY for faster projection lenses; The MITCHELL CAMERA COMPANY for a new type process projection head; MOLE-RICHARDSON COMPANY for a new type automatically controlled projection arc lamp; CHARLES HANDLEY, DAVID JOY and the NATIONAL CARBON COMPANY for improved and more stable high-intensity carbons; WINTON HOCH and the TECHNICOLOR MOTION PICTURE CORP. for an auxiliary optical system; DON MUSGRAVE and SELZNICK INTERNATIONAL PICTURES, INC. for pioneering in the use of coordinated equipment in the production, Gone with the Wind.'),
