(1318, 14, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Rey Scott for his extraordinary achievement in producing Kukan, the film record of China''s struggle, including its photography with a 16mm camera under the most difficult and dangerous conditions.'),
(1319, 14, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To The British Ministry of Information for its vivid and dramatic presentation of the heroism of the RAF in the documentary film, Target for Tonight.'),
(1320, 14, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Leopold Stokowski and his associates for their unique achievement in the creation of a new form of visualized music in Walt Disney''s production, Fantasia, thereby widening the scope of the motion picture as entertainment and as an art form.');
insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(1321, 14, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Walt Disney, William Garity, John N. A. Hawkins and the RCA Manufacturing Company for their outstanding contribution to the advancement of the use of sound in motion pictures through the production of Fantasia.'),
(1322, 14, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Walt Disney', NULL, NULL, NULL),
(1323, 14, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To ELECTRICAL RESEARCH PRODUCTS DIVISION OF WESTERN ELECTRIC CO., INC., for the development of the precision integrating sphere densitometer.'),
(1324, 14, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Sound', NULL, 'To RCA MANUFACTURING COMPANY for the design and development of the MI-3043 Uni-directional microphone.'),
(1325, 14, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Film', NULL, 'To RAY WILKINSON and the PARAMOUNT STUDIO LABORATORY for pioneering in the use of and for the first practical application to release printing of fine grain positive stock.'),
(1326, 14, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To CHARLES LOOTENS and the REPUBLIC STUDIO SOUND DEPARTMENT for pioneering the use of and for the first practical application to motion picture production of CLASS B push-pull variable area recording.'),
(1327, 14, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To WILBUR SILVERTOOTH and the PARAMOUNT STUDIO ENGINEERING DEPARTMENT for the design and computation of a relay condenser system applicable to transparency process projection, delivering considerably more usable light.'),
(1328, 14, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To PARAMOUNT PICTURES, INC., and 20TH CENTURY-FOX FILM CORP. for the development and first practical application to motion picture production of an automatic scene slating device.'),
(1329, 14, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To DOUGLAS SHEARER and the METRO-GOLDWYN-MAYER STUDIO SOUND DEPARTMENT, and to LOREN RYDER and the PARAMOUNT STUDIO SOUND DEPARTMENT for pioneering the development of fine grain emulsions for variable density original sound recording in studio production.'),
