(1396, 15, 3, 'DOCUMENTARY', true, 'Australian News & Information Bureau', NULL, 'NOTE: \"A special award to Kokoda Front Line! for its effectiveness in portraying, simply yet forcefully, the scene of war in New Guinea and for its moving presentation of the bravery and fortitude of our Australian comrades in arms.\"', NULL),
(1397, 15, 3, 'DOCUMENTARY', false, 'British Ministry of Information', NULL, NULL, NULL),
