(1402, 15, 3, 'DOCUMENTARY', true, 'Artkino', NULL, 'NOTE: \"A special award to Moscow Strikes Back for its vivid presentation of the heroism of the Russian Army and of the Russian people in the defense of Moscow, and for its achievement in so doing under conditions of extreme difficulty and danger.\"', NULL),
(1403, 15, 3, 'DOCUMENTARY', false, 'Walt Disney, Producer', NULL, NULL, NULL),
(1404, 15, 3, 'DOCUMENTARY', true, 'United States Army Special Services', NULL, 'NOTE: \"A special award to Prelude to War for its trenchant conception and authentic and stirring dramatization of the events which forced our nation into the war and of the ideals for which we fight.\"', NULL),
