(1700, 16, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To George Pal for the development of novel methods and techniques in the production of short subjects known as Puppetoons.'),
(1701, 16, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Hal B. Wallis', NULL, NULL, NULL),
(1702, 16, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Special Photographic', NULL, 'To FARCIOT EDOUART, EARLE MORGAN, BARTON THOMPSON and the PARAMOUNT STUDIO ENGINEERING and TRANSPARENCY DEPARTMENTS for the development and practical application to motion picture production of a method of duplicating and enlarging natural color photographs, transferring the image emulsions to glass plates and projecting these slides by especially designed stereopticon equipment.'),
(1703, 16, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Film', NULL, 'To PHOTO PRODUCTS DEPARTMENT, E. I. duPONT de NEMOURS AND CO., INC. for the development of fine-grain motion picture films.'),
(1704, 16, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To DANIEL J. BLOOMBERG and the REPUBLIC STUDIO SOUND DEPARTMENT for the design and development of an inexpensive method of converting Moviolas to Class B push-pull reproduction.'),
(1705, 16, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Photography', NULL, 'To CHARLES GALLOWAY CLARKE and the 20TH CENTURY-FOX STUDIO CAMERA DEPARTMENT for the development and practical application of a device for composing artificial clouds into motion picture scenes during production photography.'),
(1706, 16, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To FARCIOT EDOUART and the PARAMOUNT STUDIO TRANSPARENCY DEPARTMENT for an automatic electric transparency cueing timer.'),
(1707, 16, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To WILLARD H. TURNER and the RKO RADIO STUDIO SOUND DEPARTMENT for the design and construction of the phono-cue starter.'),
