(2155, 19, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To HARLAN L. BAUMBACH and the PARAMOUNT WEST COAST LABORATORY for an improved method for the quantitative determination of hydroquinone and metol in photographic developing baths.'),
(2156, 19, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To HERBERT E. BRITT for the development and application of formulas and equipment for producing cloud and smoke effects.'),
(2157, 19, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To BURTON F. MILLER and the WARNER BROS. STUDIO SOUND and ELECTRICAL DEPARTMENTS for the design and construction of a motion picture arc lighting generator filter.'),
(2158, 19, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To CARL FAULKNER of the 20th Century-Fox Studio Sound Department for the reversed bias method, including a double bias method for light valve and galvonometer density recording.'),
(2159, 19, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To the MOLE-RICHARDSON COMPANY for the Type 450 super high intensity carbon arc lamp.'),
(2160, 19, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Sound', NULL, 'To ARTHUR F. BLINN, ROBERT O. COOK, C. O. SLYFIELD and the WALT DISNEY STUDIO SOUND DEPARTMENT for the design and development of an audio finder and track viewer for checking and locating noise in sound tracks.');
insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
