(2378, 21, 59, 'SPECIAL FOREIGN LANGUAGE FILM AWARD', true, NULL, NULL, NULL, 'To Monsieur Vincent - voted by the Academy Board of Governors as the most outstanding foreign language film released in the United States during 1948.'),
(2379, 21, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Ivan Jandl, for the outstanding juvenile performance of 1948, as \"Karel Malik\" in The Search.'),
(2380, 21, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Sid Grauman, master showman, who raised the standard of exhibition of motion pictures.'),
(2381, 21, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Adolph Zukor, a man who has been called the father of the feature film in America, for his services to the industry over a period of forty years.'),
(2382, 21, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Walter Wanger for distinguished service to the industry in adding to its moral stature in the world community by his production of the picture Joan of Arc.'),
(2383, 21, 58, 'SPECIAL AWARD', true, NULL, NULL, 'NOTE: Presented on \"Jean Hersholt Night,\" June 26, 1949, at the Academy building.', 'To Jean Hersholt - in recognition of his service to the Academy during four terms as president.'),
(2384, 21, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Jerry Wald', NULL, NULL, NULL),
(2385, 21, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Props', NULL, 'To VICTOR CACCIALANZA, MAURICE AYERS and the PARAMOUNT STUDIO SET CONSTRUCTION DEPARTMENT for the development and application of \"Paralite,\" a new lightweight plaster process for set construction.'),
(2386, 21, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Props', NULL, 'To NICK KALTEN, LOUIS J. WITTE and the 20TH CENTURY-FOX STUDIO MECHANICAL EFFECTS DEPARTMENT for a process of preserving and flame-proofing foliage.'),
(2387, 21, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To MARTY MARTIN, JACK LANNON, RUSSELL SHEARMAN and the RKO RADIO STUDIO SPECIAL EFFECTS DEPARTMENT for the development of a new method of simulating falling snow on motion picture sets.'),
(2388, 21, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To A. J. MORAN and the WARNER BROS. STUDIO ELECTRICAL DEPARTMENT for a method of remote control for shutters on motion picture arc lighting equipment.'),
