(2496, 22, 59, 'SPECIAL FOREIGN LANGUAGE FILM AWARD', true, NULL, NULL, NULL, 'To The Bicycle Thief - voted by the Academy Board of Governors as the most outstanding foreign language film released in the United States during 1949.'),
(2497, 22, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Bobby Driscoll, as the outstanding juvenile actor of 1949.'),
(2498, 22, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Fred Astaire for his unique artistry and his contributions to the technique of musical pictures.'),
(2499, 22, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Cecil B. DeMille, distinguished motion picture pioneer, for 37 years of brilliant showmanship.'),
(2500, 22, 58, 'SPECIAL AWARD', true, NULL, NULL, NULL, 'To Jean Hersholt, for distinguished service to the motion picture industry.'),
(2501, 22, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the development and introduction of an improved safety base motion picture film.'),
(2502, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To LOREN L. RYDER, BRUCE H. DENNEY, ROBERT CARR and the PARAMOUNT STUDIO SOUND DEPARTMENT for the development and application of the supersonic playback and public address system.'),
(2503, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To M. B. PAUL for the first successful large-area seamless translucent backgrounds.'),
(2504, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To HERBERT E. BRITT for the development and application of formulas and equipment producing artificial snow and ice for dressing motion picture sets.'),
(2505, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Camera', NULL, 'To ANDRE COUTANT and JACQUES MATHOT for the design of the Eclair camerette.'),
(2506, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Editorial', NULL, 'To CHARLES R. DAILY, STEVE CSILLAG and the PARAMOUNT STUDIO ENGINEERING, EDITORIAL and MUSIC DEPARTMENTS for a new precision method of computing variable tempo click tracks.'),
(2507, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Projection', NULL, 'To the INTERNATIONAL PROJECTOR CORPORATION for a simplified and self-adjusting take-up device for projection machines.'),
(2508, 22, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Photography', NULL, 'To ALEXANDER VELCOFF for the application to production of the infra-red photographic evaluator.'),
