(2872, 25, 5, 'HONORARY FOREIGN LANGUAGE FILM AWARD', true, NULL, NULL, NULL, 'Forbidden Games - Best Foreign Language Film first released in the United States during 1952.'),
(2873, 25, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To George Alfred Mitchell for the design and development of the camera which bears his name and for his continued and dominant presence in the field of cinematography.'),
(2874, 25, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Joseph M. Schenck for long and distinguished service to the motion picture industry.'),
(2875, 25, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Merian C. Cooper for his many innovations and contributions to the art of motion pictures.'),
(2876, 25, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Harold Lloyd, master comedian and good citizen.'),
(2877, 25, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Bob Hope for his contribution to the laughter of the world, his service to the motion picture industry, and his devotion to the American premise.'),
(2878, 25, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Cecil B. DeMille', NULL, NULL, NULL),
(2879, 25, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the introduction of Eastman color negative and Eastman color print film.'),
(2880, 25, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Film', NULL, 'To ANSCO FILM DIVISION OF GENERAL ANILINE AND FILM CORPORATION for the introduction of Ansco color negative and Ansco color print film.');
