(3010, 26, 19, 'WRITING (Story and Screenplay)', true, 'Charles Brackett, Walter Reisch, Richard Breen', NULL, NULL, NULL),
(3011, 26, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Pete Smith for his witty and pungent observations on the American scene in his series of \"Pete Smith Specialties.\"'),
(3012, 26, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To 20th Century-Fox Film Corporation in recognition of their imagination, showmanship and foresight in introducing the revolutionary process known as CinemaScope.'),
(3013, 26, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Joseph I. Breen for his conscientious, open-minded and dignified management of the Motion Picture Production Code.'),
(3014, 26, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Bell and Howell Company for their pioneering and basic achievements in the advancement of the motion picture industry.'),
(3015, 26, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'George Stevens', NULL, NULL, NULL),
(3016, 26, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Systems', NULL, 'To PROFESSOR HENRI CHRETIEN and EARL SPONABLE, SOL HALPRIN, LORIN GRIGNON, HERBERT BRAGG and CARL FAULKNER of 20th Century-Fox Studios for creating, developing and engineering the equipment, processes and techniques known as CinemaScope.'),
(3017, 26, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Systems', NULL, 'To FRED WALLER for designing and developing the multiple photographic and projection systems which culminated in Cinerama.'),
(3018, 26, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Sound', NULL, 'To REEVES SOUNDCRAFT CORPORATION for their development of a process of applying stripes of magnetic oxide to motion picture film for sound recording and reproduction.'),
(3019, 26, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Editorial', NULL, 'To WESTREX CORPORATION for the design and construction of a new film editing machine.'),
