(3278, 28, 5, 'HONORARY FOREIGN LANGUAGE FILM AWARD', true, NULL, NULL, NULL, 'To Samurai, The Legend of Musashi - Best Foreign Language Film first released in the United States during 1955.'),
(3279, 28, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Lighting', NULL, 'To the NATIONAL CARBON CO. for the development and production of a high efficiency yellow flame carbon for motion picture color photography.'),
(3280, 28, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Film', NULL, 'To the EASTMAN KODAK CO. for Eastman Tri-X Panchromatic Negative Film.'),
(3281, 28, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Special Photographic', NULL, 'To FARCIOT EDOUART, HAL CORL and the PARAMOUNT STUDIO TRANSPARENCY DEPARTMENT for the engineering and development of a double-frame, triple-head background projector.'),
(3282, 28, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lenses and Filters', NULL, 'To 20TH CENTURY-FOX STUDIO and the BAUSCH & LOMB CO. for the new combination lenses for CinemaScope Photography.'),
(3283, 28, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Props', NULL, 'To WALTER JOLLEY, MAURICE LARSON and R.H. SPIES of 20th Century-Fox Studio for a spraying process which creates simulated metallic surfaces.'),
(3284, 28, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Camera Cranes', NULL, 'To STEVE KRILANOVICH for an improved camera dolly incorporating multi-directional steering.'),
(3285, 28, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To DAVE ANDERSON of 20th Century-Fox Studio for an improved spotlight capable of maintaining a fixed circle of light at constant intensity over varied distances.'),
(3286, 28, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Projection', NULL, 'To LOREN L. RYDER, CHARLES WEST, HENRY FRACKER and the PARAMOUNT STUDIOS for a projection film index to establish proper framing for various aspect ratios.'),
(3287, 28, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To FARCIOT EDOUART, HAL CORL and the PARAMOUNT STUDIO TRANSPARENCY DEPARTMENT for an improved dual stereopticon background projector.'),
