(3758, 32, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Bob Hope', NULL, NULL, NULL),
(3759, 32, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Lee De Forest for his pioneering inventions which brought sound to the motion picture.'),
(3760, 32, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Buster Keaton for his unique talents which brought immortal comedies to the screen.'),
(3761, 32, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Systems', NULL, 'To DOUGLAS G. SHEARER of Metro-Goldwyn-Mayer, Inc., and ROBERT E. GOTTSCHALK and JOHN R. MOORE of Panavision, Inc., for the development of a system of producing and exhibiting wide-film motion pictures known as Camera 65.'),
(3762, 32, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To WADSWORTH E. POHL, WILLIAM EVANS, WERNER HOPF, S.E. HOWSE, THOMAS P. DIXON, STANFORD RESEARCH INSTITUTE and TECHNICOLOR CORP., for the design and development of the Technicolor Electronic Printing Timer.'),
(3763, 32, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To WADSWORTH E. POHL, JACK ALFORD, HENRY IMUS, JOSEPH SCHMIT, PAUL FASSNACHT, AL LOFQUIST and TECHNICOLOR CORP., for the development and practical application of equipment for wet printing.'),
(3764, 32, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Projection', NULL, 'To DR. HOWARD S. COLEMAN, DR. A. FRANCIS TURNER, HAROLD H. SCHROEDER, JAMES R. BENFORD and HAROLD E. ROSENBERGER of the Bausch & Lomb Optical Co. for the design and development of the Balcold Projection Mirror.'),
(3765, 32, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To ROBERT P. GUTTERMAN of General Kinetics, Inc., and LIPSNER-SMITH CORP. for the design and development of the CF-2 Ultra-sonic Film Cleaner.'),
(3766, 32, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To UB IWERKS of Walt Disney Prods. for the design of an improved optical printer for special effects and matte shots.'),
(3767, 32, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To E.L. STONES, GLEN ROBINSON, WINFIELD HUBBARD and LUTHER NEWMAN of the Metro-Goldwyn-Mayer Studio Construction Department for the design of a multiple cable remote controlled winch.'),
