(4013, 34, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'George Seaton', NULL, NULL, NULL),
(4014, 34, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To William L. Hendricks for his outstanding patriotic service in the conception, writing and production of the Marine Corps film, A Force in Readiness, which has brought honor to the Academy and the motion picture industry.'),
(4015, 34, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Fred L. Metzler for his dedication and outstanding service to the Academy of Motion Picture Arts and Sciences.'),
(4016, 34, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Jerome Robbins for his brilliant achievements in the art of choreography on film.'),
(4017, 34, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Stanley Kramer', NULL, NULL, NULL),
(4018, 34, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Lighting', NULL, 'To SYLVANIA ELECTRIC PRODUCTS, INC., for the development of a hand held high-power photographic lighting unit known as the Sun Gun Professional.'),
(4019, 34, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To JAMES DALE, S. WILSON, H.E. RICE, JOHN RUDE, LAURIE ATKIN, WADSWORTH E. POHL, H. PEASGOOD and TECHNICOLOR CORP. for a process of automatic selective printing.'),
(4020, 34, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To 20TH CENTURY-FOX RESEARCH DEPARTMENT, under the direction of E.I. SPONABLE and HERBERT E. BRAGG, and DELUXE LABORATORIES, INC., with the assistance of F.D. LESLIE, R.D. WHITMORE, A.A. ALDEN, ENDEL POOL and JAMES B. GORDON for a system of decompressing and recomposing CinemaScope pictures for conventional aspect ratios.'),
(4021, 34, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To HURLETRON, INC., ELECTRIC EYE EQUIPMENT DIVISION, for an automatic light changing system for motion picture printers.'),
(4022, 34, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To WADSWORTH E. POHL and TECHNICOLOR CORP. for an integrated sound and picture transfer process.'),
