(4393, 37, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To William Tuttle for his outstanding make-up achievement for 7 Faces of Dr. Lao.'),
(4394, 37, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Special Photographic', NULL, 'To PETRO VLAHOS, WADSWORTH E. POHL and UB IWERKS for the conception and perfection of techniques for Color Traveling Matte Composite Cinematography.'),
(4395, 37, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To SIDNEY P. SOLOW, EDWARD H. REICHARD, CARL W. HAUGE and JOB SANDERSON of Consolidated Film Industries for the design and development of a versatile Automatic 35mm Composite Color Printer.'),
(4396, 37, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Lenses and Filters', NULL, 'To PIERRE ANGENIEUX for the development of a ten-to-one Zoom Lens for cinematography.'),
(4397, 37, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To MILTON FORMAN, RICHARD B. GLICKMAN and DANIEL J. PEARLMAN of ColorTran Industries for advancements in the design and application to motion picture photography of lighting units using quartz iodine lamps.'),
(4398, 37, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To STEWART FILMSCREEN CORPORATION for a seamless translucent Blue Screen for Traveling Matte Color Cinematography.'),
(4399, 37, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To ANTHONY PAGLIA and the 20TH CENTURY-FOX STUDIO MECHANICAL EFFECTS DEPARTMENT for an improved method of producing Explosion Flash Effects for motion pictures.'),
(4400, 37, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To EDWARD H. REICHARD and CARL W. HAUGE of Consolidated Film Industries for the design of a Proximity Cue Detector and its application to motion picture printers.'),
(4401, 37, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To EDWARD H. REICHARD, LEONARD L. SOKOLOW and CARL W. HAUGE of Consolidated Film Industries for the design and application to motion picture laboratory practice of a Stroboscopic Scene Tester for color and black-and-white film.'),
(4402, 37, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Photography', NULL, 'To NELSON TYLER for the design and construction of an improved Helicopter Camera System.'),
