(4877, 41, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Martha Raye', NULL, NULL, NULL),
(4878, 41, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To John Chambers for his outstanding makeup achievement for Planet of the Apes.'),
(4879, 41, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Onna White for her outstanding choreography achievement for Oliver!'),
(4880, 41, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Special Photographic', NULL, 'To PHILIP V. PALMQUIST of Minnesota Mining and Manufacturing Co., to DR. HERBERT MEYER of the Motion Picture and Television Research Center, and to CHARLES D. STAFFELL of the Rank Organization for the development of a successful embodiment of the reflex background projection system for composite cinematography.'),
(4881, 41, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the development and introduction of a color reversal intermediate film for motion pictures.'),
(4882, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Photography', NULL, 'To DONALD W. NORWOOD for the design and development of the Norwood Photographic Exposure Meters.'),
(4883, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To EASTMAN KODAK COMPANY and PRODUCERS SERVICE COMPANY for the development of a new high-speed step-optical reduction printer.'),
(4884, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Camera', NULL, 'To EDMUND M. DI GIULIO, NIELS G. PETERSEN and NORMAN S. HUGHES of the Cinema Product Development Company for the design and application of a conversion which makes available the reflex viewing system for motion picture cameras.'),
(4885, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Lenses and Filters', NULL, 'To OPTICAL COATING LABORATORIES, INC. for the development of an improved anti-reflection coating for photographic and projection lens systems.'),
(4886, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the introduction of a new high speed motion picture color negative film.'),
(4887, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Camera', NULL, 'To PANAVISION, INCORPORATED, for the conception, design and introduction of a 65mm hand-held motion picture camera.'),
(4888, 41, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Camera', NULL, 'To TODD-AO and MITCHELL CAMERA COMPANY for the design and engineering of the Todd-AO hand-held motion picture camera.'),
(4889, 41, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To CARL W. HAUGE and EDWARD H. REICHARD of Consolidated Film Industries and E. MICHAEL MEAHL and ROY J. RIDENOUR of Ramtronics for engineering an automatic exposure control for printing-machine lamps.'),
(4890, 41, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for a new direct positive film and to CONSOLIDATED FILM INDUSTRIES for the application of this film to the making of post-production work prints.'),
