(5437, 46, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Lew Wasserman', NULL, NULL, NULL),
(5438, 46, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Henri Langlois for his devotion to the art of film, his massive contributions in preserving its past and his unswerving faith in its future.'),
(5439, 46, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Groucho Marx in recognition of his brilliant creativity and for the unequalled achievements of the Marx Brothers in the art of motion picture comedy.'),
(5440, 46, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Lawrence Weingarten', NULL, NULL, NULL),
(5441, 46, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Camera', NULL, 'To JOACHIM GERB and ERICH KASTNER of The Arnold and Richter Company for the development and engineering of the Arriflex 35BL motion picture camera.'),
(5442, 46, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Sound', NULL, 'To MAGNA-TECH ELECTRONIC CO., INC. for the engineering and development of a high-speed re-recording system for motion picture production.'),
(5443, 46, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To WILLIAM W. VALLIANT of PSC Technology Inc., HOWARD F. OTT of Eastman Kodak Company, and GERRY DIEBOLD of The Richmark Camera Service Inc. for the development of a liquid-gate system for motion-picture printers.'),
(5444, 46, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Laboratory', NULL, 'To HAROLD A. SCHEIB, CLIFFORD H. ELLIS and ROGER W. BANKS of Research Products Incorporated for the concept and engineering of the Model 2101 optical printer for motion picture optical effects.'),
(5445, 46, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lenses and Filters', NULL, 'To ROSCO LABORATORIES, INC. for the technical advances and the development of a complete system of light-control materials for motion picture photography.'),
(5446, 46, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lenses and Filters', NULL, 'To RICHARD H. VETTER of Todd-AO Corporation for the design of an improved anamorphic focusing system for motion picture photography.'),
