(5668, 48, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Stage Operations', NULL, 'To CHADWELL O''CONNOR of the O''Connor Engineering Laboratories for the concept and engineering of a fluid-damped camera-head for motion picture photography.'),
(5669, 48, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Lighting', NULL, 'To WILLIAM F. MINER of Universal City Studios, Inc. and the WESTINGHOUSE ELECTRIC CORPORATION for the development and engineering of a solid-state, 500 kilowatt, direct-current static rectifier for motion picture lighting.'),
(5670, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To LAWRENCE W. BUTLER and ROGER BANKS for the concept of applying low inertia and stepping electric motors to film transport systems and optical printers for motion picture production.'),
(5671, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To DAVID J. DEGENKOLB and FRED SCOBEY of Deluxe General Incorporated and JOHN C. DOLAN and RICHARD DUBOIS of the Akwaklame Company for the development of a technique for silver recovery from photographic wash-waters by ion exchange.'),
(5672, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Special Photographic', NULL, 'To JOSEPH WESTHEIMER for the development of a device to obtain shadowed titles on motion picture films.'),
(5673, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To CARTER EQUIPMENT COMPANY, INC. and RAMTRONICS for the engineering and manufacture of a computerized tape punching system for programming laboratory printing machines.'),
(5674, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To HOLLYWOOD FILM COMPANY for the engineering and manufacture of a computerized tape punching system for programming laboratory printing machines.'),
(5675, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To BELL & HOWELL for the engineering and manufacture of a computerized tape punching system for programming laboratory printing machines.'),
(5676, 48, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To FREDRIK SCHLYTER for the engineering and manufacture of a computerized tape punching system for programming laboratory printing machines.'),
