(5892, 50, 53, 'SPECIAL ACHIEVEMENT AWARD', true, NULL, NULL, NULL, 'To Benjamin Burtt, Jr. for the creation of the alien, creature and robot voices featured in Star Wars.'),
(5893, 50, 55, 'SPECIAL ACHIEVEMENT AWARD (Sound Effects Editing)', true, 'Frank E. Warner', NULL, NULL, NULL),
(5894, 50, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Charlton Heston', NULL, NULL, NULL),
(5895, 50, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Margaret Booth for her exceptional contribution to the art of film editing in the motion picture industry.'),
(5896, 50, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Walter Mirisch', NULL, NULL, NULL),
(5897, 50, 64, 'SCIENTIFIC OR TECHNICAL AWARD (Class I)', true, NULL, 'Camera Cranes', NULL, 'To GARRETT BROWN and the CINEMA PRODUCTS CORPORATION ENGINEERING STAFF under the supervision of John Jurgens, for the invention and development of Steadicam.'),
(5898, 50, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Sound', NULL, 'To JOSEPH D. KELLY, EMORY M. COHEN, BARRY K. HENLEY, HAMMOND H. HOLT and JOHN AGALSOFF of Glen Glenn Sound for the concept and development of a Post-production Audio Processing System for Motion Picture Films.'),
(5899, 50, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Camera', NULL, 'To PANAVISION, INCORPORATED, for the concept and engineering of the improvements incorporated in the Panaflex Motion Picture Camera.'),
(5900, 50, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Camera', NULL, 'To N. PAUL KENWORTHY, JR. and WILLIAM R. LATADY for the invention and development of the Kenworthy Snorkel Camera System for motion picture photography.'),
(5901, 50, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Systems', NULL, 'To JOHN C. DYKSTRA for the development of a facility uniquely oriented toward visual effects photography, and to ALVAH J. MILLER and JERRY JEFFRESS for the engineering of the Electronic Motion Control System used in concert for multiple exposure visual effects motion picture photography.'),
(5902, 50, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the development and introduction of a new duplicating film for motion pictures.'),
(5903, 50, 65, 'SCIENTIFIC OR TECHNICAL AWARD (Class II)', true, NULL, 'Sound', NULL, 'To STEFAN KUDELSKI of Nagra Magnetic Recorders, Incorporated, for the engineering of the improvements incorporated in the Nagra 4.2L sound recorder for motion picture production.'),
(5904, 50, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Camera', NULL, 'To ERNST NETTMANN of the Astrovision Division of Continental Camera Systems, Incorporated, for the engineering of its Periscope Aerial Camera System.'),
(5905, 50, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Systems', NULL, 'To EECO (Electronic Engineering Company of California) for developing a method for interlocking non-sprocketed film and tape media used in motion picture production.'),
(5906, 50, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To DR. BERNHARD KÜHL and WERNER BLOCK of OSRAM, GmbH, for the development of the HMI high-efficiency discharge lamp for motion picture lighting.'),
(5907, 50, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Lighting', NULL, 'To PANAVISION, INCORPORATED, for the design of Panalite, a camera-mounted controllable light for motion picture photography.'),
(5908, 50, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Stage Operations', NULL, 'To PANAVISION, INCORPORATED, for the engineering of the Panahead gearhead for motion picture cameras.'),
(5909, 50, 66, 'SCIENTIFIC OR TECHNICAL AWARD (Class III)', true, NULL, 'Laboratory', NULL, 'To PICLEAR, INCORPORATED, for originating and developing an attachment to motion picture projectors to improve screen image quality.'),
(5910, 50, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Gordon E. Sawyer in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
(5911, 50, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Sidney Paul Solow in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
