(6012, 51, 57, 'SPECIAL ACHIEVEMENT AWARD (Visual Effects)', true, 'Les Bowie, Colin Chilvers, Denys Coop, Roy Field, Derek Meddings, Zoran Perisic', NULL, NULL, NULL),
(6013, 51, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Leo Jaffe', NULL, NULL, NULL),
(6014, 51, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Walter Lantz for bringing joy and laughter to every part of the world through his unique animated motion pictures.'),
(6015, 51, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To The Museum of Modern Art Department of Film for the contribution it has made to the public''s perception of movies as an art form.'),
(6016, 51, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Laurence Olivier for the full body of his work, for the unique achievements of his entire career and his lifetime of contribution to the art of film.'),
(6017, 51, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To King Vidor for his incomparable achievements as a cinematic creator and innovator.'),
(6018, 51, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the research and development of a Duplicating Color film for Motion Pictures.'),
(6019, 51, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Sound', NULL, 'To STEFAN KUDELSKI of Nagra Magnetic Recorders, Incorporated, for the continuing research, design and development of the Nagra Production Sound Recorder for Motion Pictures.'),
(6020, 51, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Camera', NULL, 'To PANAVISION, INCORPORATED, and its engineering staff under the direction of ROBERT E. GOTTSCHALK, for the concept, design and continuous development of the Panaflex Motion Picture Camera System.'),
(6021, 51, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To RAY M. DOLBY, IOAN R. ALLEN, DAVID P. ROBINSON, STEPHEN M. KATZ and PHILIP S. J. BOOLE of Dolby Laboratories, Incorporated, for the development and implementation of an improved Sound Recording and Reproducing System for Motion Picture Production and Exhibition.'),
(6022, 51, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To KARL MACHER and GLENN M. BERGGREN of Isco Optische Werke for the development and introduction of the Cinelux-ULTRA Lens for 35mm Motion Picture Projection.'),
(6023, 51, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To DAVID J. DEGENKOLB, ARTHUR L. FORD and FRED J. SCOBEY of DeLuxe General, Incorporated, for the development of a Method to Recycle Motion Picture Laboratory Photographic Wash Waters by Ion Exchange.'),
(6024, 51, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Systems', NULL, 'To KIICHI SEKIGUCHI of CINE-FI International for the development of the CINE-FI Auto Radio Sound System for Drive-In Theaters.'),
(6025, 51, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera Cranes', NULL, 'To LEONARD CHAPMAN of Leonard Equipment Company, for the design and manufacture of a small, mobile, motion picture camera platform known as the Chapman Hustler Dolly.'),
(6026, 51, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera Cranes', NULL, 'To JAMES L. FISHER of J.L. Fisher, Incorporated, for the design and manufacture of a small, mobile, motion picture camera platform known as the Fisher Model Ten Dolly.'),
(6027, 51, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera Cranes', NULL, 'To ROBERT STINDT of Production Grip Equipment Company, for the design and manufacture of a small, mobile, motion picture camera platform known as the Stindt Dolly.'),
(6028, 51, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Linwood G. Dunn in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
(6029, 51, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Loren L. Ryder in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
(6030, 51, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Waldon O. Watson in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
