(6137, 52, 54, 'SPECIAL ACHIEVEMENT AWARD (Sound Editing)', true, 'Alan Splet', NULL, NULL, NULL),
(6138, 52, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Robert Benjamin', NULL, NULL, NULL),
(6139, 52, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Alec Guinness for advancing the art of screen acting through a host of memorable and distinguished performances.'),
(6140, 52, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Hal Elias for his dedication and distinguished service to the Academy of Motion Picture Arts and Sciences.'),
(6141, 52, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Ray Stark', NULL, NULL, NULL),
(6142, 52, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Editorial', NULL, 'To MARK SERRURIER for the progressive development of the Moviola from the 1924 invention of his father, Iwan Serrurier, to the present Series 20 sophisticated film editing equipment.'),
(6143, 52, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To NEIMAN-TILLAR ASSOCIATES for the creative development and to MINI-MICRO SYSTEMS, INCORPORATED, for the design and engineering of an Automated Computer-Controlled Editing Sound System (ACCESS) for motion picture post-production.'),
(6144, 52, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To MICHAEL V. CHEWEY, WALTER G. EGGERS and ALLEN HECHT of M-G-M Laboratories for the development of a Computer-controlled Paper Tape Programmer System and its applications in the motion picture laboratory.'),
(6145, 52, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To IRWIN YOUNG, PAUL KAUFMAN and FREDRIK SCHLYTER of Du Art Film Laboratories, Incorporated, for the development of a Computer-controlled Paper Tape Programmer System and its applications in the motion picture laboratory.'),
(6146, 52, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Projection', NULL, 'To JAMES S. STANFIELD and PAUL W. TRESTER for the development and manufacture of a device for the repair or protection of sprocket holes in motion picture film.'),
(6147, 52, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To ZORAN PERISIC of Courier Films, Limited, for the Zoptic Special Optical Effects Device for motion picture photography.'),
(6148, 52, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To A. D. FLOWERS and LOGAN R. FRAZEE for the development of a device to control flight patterns of miniature airplanes during motion picture photography.'),
(6149, 52, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Photography', NULL, 'To PHOTO RESEARCH DIVISION OF KOLLMORGEN CORPORATION for the development of the Spectra Series II Cine Special Exposure Meter for motion picture photography.'),
