(6251, 53, 57, 'SPECIAL ACHIEVEMENT AWARD (Visual Effects)', true, 'Brian Johnson, Richard Edlund, Dennis Muren, Bruce Nicholson', NULL, NULL, NULL),
(6252, 53, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Henry Fonda, the consummate actor, in recognition of his brilliant accomplishments and enduring contribution to the art of motion pictures.'),
(6253, 53, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Laboratory', NULL, 'To LINWOOD G. DUNN, CECIL D. LOVE and ACME TOOL AND MANUFACTURING COMPANY for the concept, engineering and development of the Acme-Dunn Optical Printer for motion picture special effects.'),
(6254, 53, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera Cranes', NULL, 'To JEAN-MARIE LAVALOU, ALAIN MASSERON and DAVID SAMUELSON of Samuelson Alga Cinema S.A. and Samuelson Film Service, Limited, for the engineering and development of the Louma Camera Crane and remote control system for motion picture production.'),
(6255, 53, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Laboratory', NULL, 'To EDWARD B. KRAUSE of Filmline Corporation for the engineering and manufacture of the micro-demand drive for continuous motion picture film processors.'),
(6256, 53, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Stage Operations', NULL, 'To ROSS TAYLOR for the concept and development of a system of air guns for propelling objects used in special effects motion picture production.'),
(6257, 53, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lighting', NULL, 'To DR. BERNHARD KÜHL and DR. WERNER BLOCK of OSRAM GmbH, for the progressive engineering and manufacture of the OSRAM HMI light source for motion picture color photography.'),
(6258, 53, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lenses and Filters', NULL, 'To DAVID A. GRAFTON for the optical design and engineering of a telecentric anamorphic lens for motion picture optical effects printers.'),
(6259, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To CARTER EQUIPMENT COMPANY for the development of a continuous contact, total immersion, additive color motion picture printer.'),
(6260, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To HOLLYWOOD FILM COMPANY for the development of a continuous contact, total immersion, additive color motion picture printer.'),
(6261, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To ANDRÉ DeBRIE S.A. for the development of a continuous contact, total immersion, additive color motion picture printer.'),
(6262, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Systems', NULL, 'To CHARLES VAUGHN and EUGENE NOTTINGHAM of Cinetron Computer Systems, Incorporated, for the development of a versatile general purpose computer system for animation and optical effects motion picture photography.'),
(6263, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To JOHN W. LANG, WALTER HRASTNIK and CHARLES J. WATSON of Bell and Howell Company for the development and manufacture of a modular continuous contact motion picture film printer.'),
(6264, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Projection', NULL, 'To WORTH BAIRD of LaVezzi Machine Works, Incorporated, for the advanced design and manufacture of a film sprocket for motion picture projectors.'),
(6265, 53, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Photography', NULL, 'To PETER A. REGLA and DAN SLATER of Elicon for the development of a follow-focus system for motion picture optical effects printers and animation stands.'),
(6266, 53, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Fred Hynes, in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
