(6734, 57, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To DONALD A. ANDERSON and DIANA REINERS of 3M Company for the development of \"Cinetrak\" Magnetic Film #350/351 for motion picture sound recording.'),
(6735, 57, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To BARRY M. STULTZ, RUBEN AVILA and WES KENNEDY of Film Processing Corporation for the development of FPC 200 PB Fullcoat Magnetic Film for motion picture sound recording.'),
(6736, 57, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To BARRY M. STULTZ, RUBEN AVILA and WES KENNEDY of Film Processing Corporation for the formulation and application of an improved sound track stripe to 70mm motion picture film, and to JOHN MOSELY for the engineering research involved therein.'),
(6737, 57, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lenses and Filters', NULL, 'To KENNETH RICHTER of Richter Cine Equipment for the design and engineering of the R-2 Auto-Collimator for examining image quality at the focal plane of motion picture camera lenses.'),
(6738, 57, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Stage Operations', NULL, 'To GÜNTHER SCHAIDT and ROSCO LABORATORIES, INCORPORATED, for the development of an improved, non-toxic fluid for creating fog and smoke for motion picture production.'),
(6739, 57, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Special Photographic', NULL, 'To JOHN WHITNEY, JR. and GARY DEMOS of Digital Productions, Incorporated, for the practical simulation of motion picture photography by means of computer-generated images.'),
(6740, 57, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To NAT TIFFEN of Tiffen Manufacturing Corporation for the production of high-quality, durable, laminated color filters for motion picture photography.'),
(6741, 57, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To DONALD TRUMBULL, JONATHAN ERLAND, STEPHEN FOG and PAUL BURK of Apogee, Incorporated, for the design and development of the \"Blue Max\" high-power, blue-flux projector for traveling matte composite photography.'),
(6742, 57, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To JONATHAN ERLAND and ROBERT BEALMEAR of Apogee, Incorporated, for an innovative design for front projection screens and an improved method for their construction.'),
(6743, 57, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera', NULL, 'To HOWARD J. PRESTON of Preston Cinema Systems for the design and development of a variable speed control device with automatic exposure compensation for motion picture cameras.'),
