(6849, 58, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Charles ''Buddy'' Rogers', NULL, NULL, NULL),
(6850, 58, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Paul Newman, in recognition of his many and memorable compelling screen performances and for his personal integrity and dedication to his craft.'),
(6851, 58, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Alex North, in recognition of his brilliant artistry in the creation of memorable music for a host of distinguished motion pictures.'),
(6852, 58, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Systems', NULL, 'To IMAX SYSTEMS CORPORATION for a method of filming and exhibiting high-fidelity, large-format, wide angle motion pictures.'),
(6853, 58, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', NULL, 'To ERNST NETTMANN of E.F. Nettmann & Associates for the invention, and to EDWARD PHILLIPS and CARLOS DeMATTOS of Matthews Studio Equipment, Inc. for the development, of the Cam-Remote for motion picture photography.'),
(6854, 58, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lighting', NULL, 'To MYRON GORDIN, JOE P. CROOKHAM, JIM DROST and DAVID CROOKHAM of Musco Mobile Lighting, Ltd., for the invention of a method of transporting adjustable, high-intensity luminaires and their application to the motion picture industry.'),
(6855, 58, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Cartoon Process', NULL, 'To DAVID W. SPENCER for the development of an Animation Photo Transfer (APT) process.'),
(6856, 58, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To HARRISON & HARRISON, OPTICAL ENGINEERS, for the invention and development of Harrison Diffusion filters for motion picture photography.'),
(6857, 58, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera', NULL, 'To LARRY BARTON of Cinematography Electronics, Inc., for a Precision Speed Crystal-Controlled Device for motion picture photography.'),
(6858, 58, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera', NULL, 'To ALAN LANDAKER of The Burbank Studios for the Mark III Camera Drive for motion picture photography.'),
(6859, 58, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To John H. Whitney, Sr. for Cinematic Pioneering.'),
