insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(7081, 60, 19, 'WRITING (Screenplay Written Directly for the Screen)', true, 'John Patrick Shanley', NULL, NULL, NULL),
(7082, 60, 19, 'WRITING (Screenplay Written Directly for the Screen)', false, 'Woody Allen', NULL, NULL, NULL),
(7083, 60, 55, 'SPECIAL ACHIEVEMENT AWARD (Sound Effects Editing)', true, 'Stephen Flick, John Pospisil', NULL, NULL, NULL),
(7084, 60, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Billy Wilder', NULL, NULL, NULL),
(7085, 60, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Fred Hynes'),
(7086, 60, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Lighting', NULL, 'To BERNHARD KÜHL and WERNER BLOCK and to the OSRAM GmbH RESEARCH AND DEVELOPMENT DEPARTMENT for the invention and the continuing improvement of the OSRAM HMI light source for motion picture photography.'),
(7087, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Projection', NULL, 'To WILLI BURTH and KINOTONE CORPORATION for the invention and development of the Non-rewind Platter System for motion picture presentations.'),
(7088, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Editorial', NULL, 'To MONTAGE GROUP, LTD. for the development, and to RONALD C. BARKER and CHESTER L. SCHULER for the invention, of the Montage Picture Processor electronic film editing system.'),
(7089, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Laboratory', NULL, 'To COLIN F. MOSSMAN and RANK FILM LABORATORIES'' DEVELOPMENT GROUP for creating a fully-automated, film handling system for improving productivity of high speed film processing.'),
(7090, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the development of Eastman Color High Speed Daylight Negative Film 5297/7297.'),
(7091, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the development of Eastman Color High Speed SA Negative Film 5295 for blue-screen traveling matte photography.'),
(7092, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', NULL, 'To FRITZ GABRIEL BAUER for the invention and development of the improved features of the Moviecam Camera System.'),
(7093, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Special Photographic', NULL, 'To ZORAN PERISIC of Courier Films Ltd. for the Zoptic dual-zoom front projection system for visual effects photography.'),
(7094, 60, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lenses and Filters', NULL, 'To the CARL ZEISS COMPANY for the design and development of a series of super-speed lenses for motion picture photography.'),
(7095, 60, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Sound', NULL, 'To IOAN ALLEN of Dolby Laboratories, Inc., for the Cat. 43 playback-only noise reduction unit and its practical application to motion picture sound recordings.'),
(7096, 60, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To JOHN EPPOLITO, WALLY GENTLEMAN, WILLIAM MESA, LES PAUL ROBLEY and GEOFFREY H. WILLIAMSON for refinements to a dual screen, front projection, image-compositing system.'),
(7097, 60, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To JAN JACOBSEN for the application of a dual screen, front projection system to motion picture special effects photography.'),
(7098, 60, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To THAINE MORRIS and DAVID PIER for the development of DSC Spark Devices for motion picture special effects.'),
(7099, 60, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To TADEUZ KRZANOWSKI of Industrial Light and Magic, Inc., for the development of a Wire Rig Model Support Mechanism used to control the movements of miniatures in special effects.'),
(7100, 60, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera', NULL, 'To DAN C. NORRIS and TIM COOK of Norris Film Products for the development of a single-frame exposure system for motion picture photography.'),
