insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(7441, 63, 57, 'SPECIAL ACHIEVEMENT AWARD (Visual Effects)', true, 'Eric Brevig, Rob Bottin, Tim McGovern, Alex Funke', NULL, NULL, NULL),
(7442, 63, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Sophia Loren, one of the genuine treasures of world cinema who, in a career rich with memorable performances, has added permanent luster to our art form.'),
(7443, 63, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Myrna Loy, in recognition of her extraordinary qualities both on screen and off, with appreciation for a lifetime''s worth of indelible performances.'),
(7444, 63, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'David Brown and Richard D. Zanuck', NULL, NULL, NULL),
(7445, 63, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Stefan Kudelski'),
(7446, 63, 60, 'SCIENTIFIC OR TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Film', NULL, 'To EASTMAN KODAK COMPANY for the development of T-Grain technology and the introduction of EXR color negative films which utilize this technology.'),
(7447, 63, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Special Photographic', NULL, 'To BRUCE WILTON and CARLOS ICINKOFF of Mechanical Concepts, Incorporated, for the development of the Mechanical Concepts Optical Printer Platform.'),
(7448, 63, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', NULL, 'To the ENGINEERING DEPARTMENT OF ARNOLD & RICHTER for the continued design improvements of the Arriflex BL Camera System, culminating in the 35BL-4S model.'),
(7449, 63, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Film', NULL, 'To the FUJI PHOTO FILM COMPANY, LIMITED, for the development and introduction of the F-Series of color negative films covering the range of film speeds from EI 64 to EI 500.'),
(7450, 63, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Laboratory', NULL, 'To MANFRED G. MICHELSON of Technical Film Systems, Incorporated, for the design and development of the first sprocket-driven film transport system for color print film processors which permits transport speeds in excess of 600 feet per minute.'),
(7451, 63, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Laboratory', NULL, 'To JOHN W. LANG, WALTER HRASTNIK and CHARLES J. WATSON of Bell and Howell Company for the development and manufacture of a modular continuous contact motion picture film printer.'),
(7452, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Photography', NULL, 'To WILLIAM L. BLOWERS of Belco Associates, Incorporated and THOMAS F. DENOVE for the development and manufacture of the Belco/Denove Cinemeter. This digital/analog exposure meter was specifically and uniquely designed for the cinematographer.'),
(7453, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To IAIN NEIL for optical design; TAKUO MIYAGISHIMA for the mechanical design; and PANAVISION, INCORPORATED, for the concept and development of the Primo Series of spherical prime lenses for 35mm cinematography.'),
(7454, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To CHRISTOPHER S. GILMAN and HARVEY HUBERT, JR. of the Diligent Dwarves Effects Lab for the development of the Actor Climate System, consisting of heat-transferring undergarments.'),
(7455, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To JIM GRAVES of J&G Enterprises for the development of the Cool Suit System, consisting of heat-transferring undergarments.'),
(7456, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To BENGT O. ORHALL, KENNETH LUND, BJORN SELIN and KJELL HOGBERG of AB Film-Teknik for the development and manufacture of the Mark IV film subtitling processor, which has increased the speed, simplified the operation and improved the quality of subtitling.'),
(7457, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lighting', NULL, 'To RICHARD MULA and PETE ROMANO of HydroImage, Incorporated, for the development of the SeaPar 1200 watt HMI Underwater Lamp.'),
(7458, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lighting', NULL, 'To DEDO WEIGERT of Dedo Weigert Film GmbH for the development of the Dedolight, a miniature low-voltage tungsten-halogen lighting fixture.'),
(7459, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Film', NULL, 'To DR. FRED KOLB, JR. and PAUL PREO for the concept and development of a 35mm projection test film.'),
(7460, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lighting', NULL, 'To PETER BALDWIN for the design; DR. PAUL KIANKHOOY and the LIGHTMAKER COMPANY for the development of the Lightmaker AC/DC HMI Ballast.'),
(7461, 63, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Systems', NULL, 'To the ALL-UNION CINEMA AND PHOTO RESEARCH INSTITUTE (NIKFI) for continuously improving and providing 3-D presentations to Soviet motion picture audiences for the last 25 years.'),
(7462, 63, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Roderick T. Ryan in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
(7463, 63, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Don Trumbull in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
(7464, 63, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Geoffrey H. Williamson in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
