(7570, 64, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Satyajit Ray, in recognition of his rare mastery of the art of motion pictures, and of his profound humanitarian outlook, which has had an indelible influence on filmmakers and audiences throughout the world.'),
(7571, 64, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'George Lucas', NULL, NULL, NULL),
(7572, 64, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Ray Harryhausen'),
(7573, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lenses and Filters', NULL, 'To IAIN NEIL for the optical design; ALBERT SAIKI for the mechanical design; and PANAVISION, INCORPORATED, for the concept and development of the Primo Zoom Lens for 35mm cinematography.'),
(7574, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Stage Operations', NULL, 'To GEORG THOMA for the design; HEINZ FEIERLEIN and the ENGINEERING DEPARTMENT OF SACHTLER AG for the development of a range of fluid tripod heads.'),
(7575, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Stage Operations', NULL, 'To HARRY J. BAKER for the design and development of the first full fluid-action tripod head with adjustable degrees of viscous drag.'),
(7576, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Stage Operations', NULL, 'To GUIDO CARTONI for his pioneering work in developing the technology to achieve selectable and repeatable viscous drag modules in fluid tripod heads.'),
(7577, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Systems', NULL, 'To RAY FEENEY, RICHARD KEENEY and RICHARD J. LUNDELL for the software development and adaptation of the Solitaire Film Recorder that provides a flexible, cost-effective film recording system.'),
(7578, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Systems', NULL, 'To FAZ FAZAKAS, BRIAN HENSON, DAVE HOUSMAN, PETER MILLER and JOHN STEPHENSON for the development of the Henson Performance Control System.'),
(7579, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lighting', NULL, 'To MARIO CELSO for his pioneering work in the design, development and manufacture of equipment for carbon arc and xenon power supplies and igniters used in motion picture projection.'),
(7580, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Systems', NULL, 'To RANDY CARTWRIGHT, DAVID B. COONS, LEM DAVIS, THOMAS HAHN, JAMES HOUSTON, MARK KIMBALL, DYLAN W. KOHLER, PETER NYE, MICHAEL SHANTZIS, DAVID F. WOLF and the WALT DISNEY FEATURE ANIMATION DEPARTMENT for the design and development of the \"CAPS\" production system for feature film animation.'),
(7581, 64, 61, 'SCIENTIFIC OR TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Stage Operations', NULL, 'To GEORGE WORRALL for the design, development and manufacture of the Worrall geared camera head for motion picture production.'),
(7582, 64, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To ROBERT W. STOKER, JR., for the design and development of a cobweb gun, for applying non-toxic cobweb effects on motion picture sets with both safety and ease of operation.'),
(7583, 64, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To JAMES DOYLE for the design and development of the Dry Fogger, which uses liquid nitrogen to produce a safe, dense, low-hanging fog effects.'),
(7584, 64, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To DICK CAVDEK, STEVE HAMERSKI and OTTO NEMENZ INTERNATIONAL, INCORPORATED for the opto-mechanical design and development of the Canon/Nemenz Zoom Lens.'),
(7585, 64, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To KEN ROBINGS and CLAIRMONT CAMERA for the opto-mechanical design and development of the Canon/Clairmont Camera Zoom Lens.'),
(7586, 64, 63, 'SCIENTIFIC OR TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', NULL, 'To CENTURY PRECISION OPTICS for the opto-mechanical design and development of the Canon/Century Precision Optics Zoom Lens.'),
(7587, 64, 46, 'AWARD OF COMMENDATION', true, NULL, NULL, NULL, 'To Pete Comandini, Richard T. Dayton, Donald Hagans and Richard T. Ryan of YCM Laboratories for the creation and development of a motion picture film restoration process using liquid gate and registration correction on a contact printer.'),
(7588, 64, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Richard J. Stumpf for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
(7589, 64, 52, 'MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Joseph Westheimer for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
