(7823, 66, 50, 'JEAN HERSHOLT HUMANITARIAN AWARD', true, 'Paul Newman', NULL, NULL, NULL),
(7824, 66, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Deborah Kerr, in appreciation for a full career''s worth of elegant and beautifully crafted performances.'),
(7825, 66, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Petro Vlahos'),
(7826, 66, 60, 'SCIENTIFIC AND TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Lenses and Filters', NULL, 'To PANAVISION for the Auto Panatar anamorphic photographic lens.'),
(7827, 66, 60, 'SCIENTIFIC AND TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Laboratory', NULL, 'To MANFRED G. MICHELSON of Technical Film Systems, Incorporated, for the design and development of the first sprocket-driven film transport system for color print film processors which permits transport speeds in excess of 600 feet per minute.'),
(7828, 66, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Systems', NULL, 'To MARK LEATHER, LES DITTERT, DOUGLAS SMYTHE and GEORGE JOBLOVE for the concept and development of the Digital Motion Picture Retouching System for removing visible rigging and dirt/damage artifacts from original motion picture imagery.'),
(7829, 66, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', NULL, 'To FRITZ GABRIEL BAUER for the design, development and manufacture of the Moviecam Compact Modular 35mm motion picture camera system.'),
(7830, 66, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lighting', NULL, 'To WALLY MILLS for the concept; and GARY STADLER and GUSTAVE PARADA for the design of the Cinemills Lamp Protection System.'),
(7831, 66, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lighting', NULL, 'To GARY NUZZI, DAVID JOHNSRUD and WILLIAM BLETHEN for the design and development of the Unilux H3000 Strobe Lighting System.'),
(7832, 66, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To HARRY J. BAKER for the design and development of the Ronford-Baker Metal Tripods for motion picture photography.'),
(7833, 66, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Sound', NULL, 'To MICHAEL DORROUGH for the design and development of the compound meter known as the Dorrough Audio Level Meter.'),
(7834, 66, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To DAVID DEGENKOLB for the development of a Silver Recovery Ion Exchange System to eliminate hazardous waste (silver ion) in wash water and allow recycling of this water.'),
