(8089, 68, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Donald C. Rogers'),
(8090, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', NULL, 'To ARNOLD AND RICHTER CINE TECHNIK for the development of the Arriflex 535 Series of Cameras for motion picture cinematography.'),
(8091, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To DIGITAL THEATER SYSTEMS for the design and development of the DTS Digital Sound System for motion picture exhibition.'),
(8092, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To DOLBY LABORATORIES for the design and development of the SR-D Digital Sound System for motion picture exhibition.'),
(8093, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To SONY CORPORATION for the design and development of the SDDS Digital Sound System for motion picture exhibition.'),
(8094, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To HOWARD FLEMMING and RONALD UHLIG for their pioneering work leading to motion picture digital sound.'),
(8095, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Photography', NULL, 'To RONALD C. GOODMAN, ATTILA SZALAY, STEVEN SASS and SPACECAM SYSTEMS, INC. for the design of the SpaceCam gyroscopically stabilized Camera System.'),
(8096, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To COLIN MOSSMAN, JOE WARY, HANS LEISINGER, GERALD PAINTER and DELUXE LABORATORIES for the design and development of the Deluxe Quad Format Digital Sound Printing Head.'),
(8097, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', NULL, 'To DAVID GILMARTIN, JOHANNES BORGGREBE, JEAN-PIERRE GAGNON, FRANK RICOTTA and TECHNICOLOR, INC. for the design and development of the Technicolor Contact Printer Sound Head.'),
(8098, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lenses and Filters', NULL, 'To IAIN NEIL for the optical design; RICK GELBARD for the mechanical design; ERIC DUBBERKE for the engineering and PANAVISION INTERNATIONAL, L.P., for the development of the Primo 3:1 Zoom Lens.'),
(8099, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', NULL, 'To MARTIN S. MUELLER for the design and development of the MSM 9801 IMAX 65mm/15 perf production motion picture camera.'),
(8100, 68, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Special Photographic', NULL, 'To ALVY RAY SMITH, ED CATMULL, THOMAS PORTER and TOM DUFF for their pioneering inventions in Digital Image Compositing.'),
(8101, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Sound', NULL, 'To PASCAL CHEDEVILLE for the design of the L.C. Concept Digital Sound System for motion picture exhibition.'),
(8102, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Sound', NULL, 'To JAMES DEAS of the Warner Bros. Studio Facility for the design and subsequent development of an Automated Patchbay and Metering System for motion picture sound transfer and dubbing operations.'),
(8103, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Sound', NULL, 'To CLAY DAVIS and JOHN CARTER of Todd-AO for their pioneering efforts in creating an Automated Patchbay System for motion picture sound transfer and dubbing operations.'),
(8104, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera', NULL, 'To AL JENSEN, CHUCK HEADLEY, JEAN MESSNER and HAZEM NABULSI of CEI Technology for producing a self-contained, flicker-free Color Video-Assist Camera.'),
(8105, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Camera', NULL, 'To PETER DENZ of Präzisions-Entwicklung Denz for developing a flicker-free Color Video-Assist Camera.'),
(8106, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To DAVID PRINGLE and YAN ZHONG FANG for the design and development of \"Lightning Strikes,\" a flexible, high-performance electronic lightning effect system.'),
(8107, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Sound', NULL, 'To BHP, INCORPORATED for their pioneering efforts developing Digital Sound Printing Heads for motion pictures.'),
(8108, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', NULL, 'To JOE FINNEGAN (a.k.a. Joe Yrigoyen) for his pioneering work in developing the Air Ram for motion picture stunt effects.'),
(8109, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To GARY DEMOS, DAVID RUHOFF, DAN CAMERON and MICHELLE FERAUD for their pioneering efforts in the creation of the Digital Productions Digital Film Compositing System.'),
(8110, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To DOUGLAS SMYTHE, LINCOLN HU, DOUGLAS S. KAY and INDUSTRIAL LIGHT AND MAGIC for their pioneering efforts in the creation of the ILM Digital Film Compositing System.'),
(8111, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', NULL, 'To the COMPUTER FILM COMPANY for their pioneering efforts in the creation of the CFC Digital Film Compositing System.'),
(8112, 68, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', NULL, 'To INSTITUT NATIONAL POLYTECHNIQUE DE TOULOUSE for the concept; KODAK PATHE CTP CINE for the prototype; and ECLAIR LABORATORIES and MARTINEAU INDUSTRIES for the development and further implementation of the Toulouse Electrolytic Silver Recovery Cell.'),
