insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(8761, 73, 19, 'WRITING (Screenplay Written Directly for the Screen)', false, 'Screenplay by David Franzoni and John Logan and William Nicholson; Story by David Franzoni', NULL, NULL, NULL),
(8762, 73, 19, 'WRITING (Screenplay Written Directly for the Screen)', false, 'Written by Kenneth Lonergan', NULL, NULL, NULL),
(8763, 73, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Jack Cardiff, master of light and color.'),
(8764, 73, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Ernest Lehman, in appreciation of a body of varied and enduring work.'),
(8765, 73, 49, 'IRVING G. THALBERG MEMORIAL AWARD', true, 'Dino De Laurentiis', NULL, NULL, NULL),
(8766, 73, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Irwin W. Young'),
(8767, 73, 60, 'SCIENTIFIC AND TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Special Photographic', 'Their broad professional influence in the industry continues to inspire and contribute to the advancement of computer-generated imagery for motion pictures.', 'To ROB COOK, LOREN CARPENTER and ED CATMULL for their significant advancements to the field of motion picture rendering as exemplified in Pixar''s \"Renderman.\"'),
(8768, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', 'This camera brings the full uncompromised performance of larger heavy-duty cameras to the lightest weight category with ruggedness and advanced features previously expected only in specialized or effects cameras.', 'To AL MAYER, SR. and AL MAYER, JR., for the mechanical design, IAIN NEIL for the optical design and BRIAN DANG for the electronic design of the Panavision Millennium XL Camera System.'),
(8769, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Laboratory', 'This release print system at Deluxe Laboratories utilizes a revolutionary design allowing for higher print volumes, reduced space requirements for loop racks and elevators, and safer operation.', 'To JOE WARY, GERALD PAINTER and COLIN F. MOSSMAN for the design and development of the Deluxe Laboratories Multi Roller Film Transport System.'),
(8770, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', 'This camera motor, operated with programmable microprocessors, achieves an unprecedented range of precisely controlled speeds in stand-alone cameras or when synchronized to motion-control systems.', 'To ALVAH J. MILLER and PAUL JOHNSON of Lynx Robotics for the electronic and software design of the Lynx C-50 Camera Motor System.'),
(8771, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', '[These] digital audio dubbers have afforded the post-production community a faster, more cost-effective means of playing back hundreds of digital audio tracks for pre-mixing or final mixing in creating motion picture sound tracks. They also offer individual track slipping in multiple track configurations, random access recall, and both destructive and non-destructive editing capabilities, eliminating the requirements for razor blade conforming.', 'To AKAI DIGITAL for the design and development of the DD8plus digital audio dubber specifically designed for the motion picture industry.'),
(8772, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', '[These] digital audio dubbers have afforded the post-production community a faster, more cost-effective means of playing back hundreds of digital audio tracks for pre-mixing or final mixing in creating motion picture sound tracks. They also offer individual track slipping in multiple track configurations, random access recall, and both destructive and non-destructive editing capabilities, eliminating the requirements for razor blade conforming.', 'To FAIRLIGHT for the design and development of the DAD digital audio dubber specifically designed for the motion picture industry.'),
(8773, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', '[These] digital audio dubbers have afforded the post-production community a faster, more cost-effective means of playing back hundreds of digital audio tracks for pre-mixing or final mixing in creating motion picture sound tracks. They also offer individual track slipping in multiple track configurations, random access recall, and both destructive and non-destructive editing capabilities, eliminating the requirements for razor blade conforming.', 'To ADVANCED DIGITAL SYSTEMS GROUP (ADSG) for the design and development of the Sony DADR 5000 digital audio dubber specifically designed for the motion picture industry.'),
(8774, 73, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Sound', '[These] digital audio dubbers have afforded the post-production community a faster, more cost-effective means of playing back hundreds of digital audio tracks for pre-mixing or final mixing in creating motion picture sound tracks. They also offer individual track slipping in multiple track configurations, random access recall, and both destructive and non-destructive editing capabilities, eliminating the requirements for razor blade conforming.', 'To TIMELINE, INCORPORATED for the design and development of the MMR 8 digital audio dubber specifically designed for the motion picture industry.'),
(8775, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lighting', 'With the ability to dim these very high powered lights at essentially constant Kelvin temperature and without flicker, these units produce a bright and even light source for general set lighting. The availability of very high wattage units allows production to extend the hours of work past the time when the crew would otherwise have \"lost the light.\"', 'To LEONARD PINCUS, ASHOT NALBANDYAN, GEORGE JOHNSON, THOMAS KONG and DAVID PRINGLE for the design and development of the SoftSun low pressure xenon long-arc light sources, their power supplies and fixtures.'),
(8776, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', 'Considered a standard of the industry, the Fan Descender provides a means for significantly increasing the safety of very high stunt falls. The system permits falls to be made under controlled deceleration and with a highly predictable stopping point without limitation of camera angles.', 'To VIC ARMSTRONG for the refinement and application to the film industry of the Fan Descender for accurately and safely arresting the descent of stunt persons in high freefalls.'),
(8777, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Stage Operations', 'This unique photographic scenic backing allows a smooth transition from day to night views with a single backing. The Roscolight backings provide an important new creative tool to filmmakers, saving time, money and stage space.', 'To PHILIP GREENSTREET of Rosco Laboratories for the concept and development of the Roscolight Day/Night Backdrop.'),
(8778, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', 'These projection lenses provide a significant improvement in the quality of the cinema viewing experience.', 'To UDO SCHAUSS, HILDEGARD EBBESMEIER and KARL LENHARDT for the optical design, and RALF LINN and NORBERT BRINKER for the mechanical design of the Schneider Super Cinelux lenses for motion picture projection.'),
(8779, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Lenses and Filters', 'The unique optical design of the Ultra-Star Plus projection lenses achieves unprecedented edge-to-edge uniformity of illumination, combined with a significant increase in screen brightness, thus providing a substantial improvement in the cinema viewing experience.', 'To GLENN M. BERGGREN for the concept, HORST LINGE for research and development, and WOLFGANG REINECKE for the optical design of the ISCO Ultra-Star Plus lenses for motion picture projection.'),
(8780, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Systems', 'These systems digitally record live action camera and axis data with practically no impact on the live action production process, allowing compositing for visual effects to become faster and more cost-effective.', 'To BILL TONDREAU of Kuper Systems, ALVAH J. MILLER and PAUL JOHNSON of Lynx Robotics, and DAVID STUMP of Visual Effects Rental Services for the conception, design and development of data capture systems that enable superior accuracy, efficiency and economy in the creation of composite imagery.'),
(8781, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', 'This system streamlines the creation of 3D computer graphics models by allowing artists to convert the data from automatically scanned physical models into a user-specified configuration of patches well suited for use in computer applications.', 'To VENKAT KRISHNAMURTHY for the creation of the Paraform Software for 3D Digital Form Development.'),
(8782, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Special Photographic', 'This component of the Manex Visual Effects Virtual Cinematography System provides theatrical-quality virtual settings.', 'To GEORGE BORSHUKOV, KIM LIBRERI and DAN PIPONI for the development of a system for image-based rendering allowing choreographed camera movements through computer graphic reconstructed sets.'),
(8783, 73, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Laboratory', 'The LAD system has become the standard method used by film laboratories and digital film recording facilities for the effecient and uniform control of color and exposure in camera negatives, interpositives and duplicate negatives.', 'To JOHN P. PYTLAK for the development of the Laboratory Aim Density (LAD) system.'),
(8784, 73, 46, 'AWARD OF COMMENDATION', true, NULL, NULL, 'The adoption of the TASA loudness standard has led directly to better sound in the cinema for trailers and features alike.', 'To Ioan Allen for the concept, Robin Bransbury for the design and Mark Harrah for the implementation of the Trailer Audio Standards Association (TASA) Loudness Standard.'),
(8785, 73, 51, 'JOHN A. BONNER MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To N. Paul Kenworthy, Jr. in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
