insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(10201, 84, 48, 'HONORARY AWARD', true, NULL, NULL, NULL, 'To Dick Smith for his unparalleled mastery of texture, shade, form and illusion.'),
(10202, 84, 47, 'GORDON E. SAWYER AWARD', true, NULL, NULL, NULL, 'Douglas Trumbull'),
(10203, 84, 60, 'SCIENTIFIC AND TECHNICAL AWARD (Academy Award of Merit)', true, NULL, 'Special Photographic', 'The ARRILASER film recorder demonstrates a high level of engineering resulting in a compact, user-friendly, low-maintenance device, while at the same time maintaining outstanding speed, exposure ratings and image quality.', 'To FRANZ KRAUS, JOHANNES STEURER and WOLFGANG RIEDEL for the design and development of the ARRILASER Film Recorder.'),
(10204, 84, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera', 'The Phantom family of high-speed digital cameras, including the Phantom Flex and HD Gold, provide imagery at speeds and efficacy surpassing photochemical technology, while seamlessly intercutting with conventional film production.', 'To RADU CORLAN, ANDY JANTZEN, PETRU POP and RICHARD F. TOFTNESS for the design and engineering of the Phantom family of high-speed cameras for motion picture production.'),
(10205, 84, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Lenses and Filters', 'The Master Primes have achieved a full stop advance in speed over existing lenses, while maintaining state-of-the-art optical quality. This lens family was also the first to eliminate the magnification change that accompanied extreme focus shifts.', 'To DR. JÜRGEN NOFFKE for the optical design and UWE WEBER for the mechanical design of the ARRI Zeiss Master Prime Lenses for motion picture photography.'),
(10206, 84, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera Cranes', 'The Pictorvision Eclipse system allows cinematographers to capture aerial footage at faster flying speeds with aggressive platform maneuvering.', 'To MICHAEL LEWIS, GREG MARSDEN, RAIGO ALAS and MICHAEL VELLEKOOP for the concept, design and implementation of the Pictorvision Eclipse, an electronically stabilized aerial camera platform.'),
(10207, 84, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Camera Cranes', 'This versatile family of 5-axis camera and lens stabilizers allows any standard motion picture camera to be fitted into the open architecture of the structure. The system can be quickly balanced and made ready for shooting platforms such as helicopters, boats, camera cars or cranes.', 'To E.F. \"BOB\" NETTMANN for the concept and system architecture, MICHAEL SAYOVITZ for the electronic packaging and integration, BRAD FRITZEL for the electronic engineering, and FRED MILLER for the mechanical engineering of the Stab-C Classic, Super-G and Stab-C Compact stabilizing heads.'),
(10208, 84, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Laboratory', 'The \"Lowry Process\" uses advanced GPU-accelerated, motion estimation-based image processing tools to enhance image quality.', 'To JOHN D. LOWRY, IAN CAVÉN, IAN GODIN, KIMBALL THURSTON and TIM CONNOLLY for the development of a unique and efficient system for the reduction of noise and other artifacts, thereby providing high-quality images required by the filmmaking process.'),
(10209, 84, 61, 'SCIENTIFIC AND TECHNICAL AWARD (Scientific and Engineering Award)', true, NULL, 'Film', 'Specifically designed for laser film recording and widely used in the industry today, the high-resolution FUJIFILM ETERNA-RDS 4791 film stock is an important step in protecting the heritage of the motion picture industry.', 'To FUJIFILM CORPORATION, HIDEYUKI SHIRAI, DR. KATSUHISA OOZEKI and HIROSHI HIRANO for the design and development of the FUJIFILM black and white recording film ETERNA-RDS 4791 for use in the archival preservation of film and digital images.'),
(10210, 84, 63, 'SCIENTIFIC AND TECHNICAL AWARD (Technical Achievement Award)', true, NULL, 'Digital Imaging Technology', 'This work allowed, for the first time, unified and efficient rendering of volumetric effects such as smoke and clouds, together with other computer graphics objects, in a micro-polygon imaging pipeline.', 'To ANDREW CLINTON and MARK ELENDT for the invention and integration of micro-voxels in the Mantra software.'),
(10211, 84, 51, 'JOHN A. BONNER MEDAL OF COMMENDATION', true, NULL, NULL, NULL, 'To Jonathan Erland in appreciation for outstanding service and dedication in upholding the high standards of the Academy of Motion Picture Arts and Sciences.'),
