insert into nominations (id, ceremony_number, category_id, exact_category, winner, citation_name, detail, note, citation) values
(10321, 85, 45, 'VISUAL EFFECTS', false, 'Janek Sirrs, Jeff White, Guy Williams and Dan Sudick', NULL, NULL, NULL),
(10322, 85, 45, 'VISUAL EFFECTS', false, 'Richard Stammers, Trevor Wood, Charley Henley and Martin Hill', NULL, NULL, NULL),
