-- Academy Awards, normalized.
-- Source data: David V. Lu!!, oscar_data (BSD-2-Clause)
-- https://github.com/DLu/oscar_data
-- A curated scrape of the official Academy Awards Database
-- (awardsdatabase.oscars.org), ceremonies 1–98, film years 1927/28–2025.
--
-- Copyright (c) 2022, David V. Lu!!
-- Redistribution and use in source and binary forms, with or without
-- modification, are permitted provided that the copyright notice and the
-- BSD-2-Clause conditions are retained. See the dataset repository.

create table if not exists ceremonies (
  number     integer primary key,
  film_year  text not null,
  year_start integer not null
);

create table if not exists categories (
  id             integer primary key,
  canonical_name text not null unique,
  class          text not null,
  sort_order     integer not null
);

create table if not exists films (
  id              integer primary key,
  canonical_title text not null,
  imdb_id         text unique
);

create table if not exists entities (
  id             integer primary key,
  canonical_name text not null,
  imdb_id        text unique,
  kind           text not null check (kind in ('person', 'company', 'unknown'))
);

create table if not exists nominations (
  id               integer primary key,
  ceremony_number  integer not null references ceremonies (number),
  category_id      integer not null references categories (id),
  exact_category   text not null,
  winner           boolean not null,
  citation_name    text,
  detail           text,
  note             text,
  citation         text
);

create table if not exists nomination_films (
  nomination_id integer not null references nominations (id),
  position      smallint not null,
  film_id       integer not null references films (id),
  billed_title  text not null,
  primary key (nomination_id, position)
);

create table if not exists nomination_entities (
  nomination_id integer not null references nominations (id),
  position      smallint not null,
  entity_id     integer not null references entities (id),
  billed_name   text not null,
  primary key (nomination_id, position)
);


create index if not exists nominations_ceremony_idx on nominations (ceremony_number);
create index if not exists nominations_category_idx on nominations (category_id);
create index if not exists nominations_winner_idx on nominations (winner);
create index if not exists nomination_films_film_idx on nomination_films (film_id);
create index if not exists nomination_entities_entity_idx on nomination_entities (entity_id);
create index if not exists films_title_lower_idx on films (lower(canonical_title));
create index if not exists entities_name_lower_idx on entities (lower(canonical_name));

create or replace view v_ballots as
select
  n.id as nomination_id,
  n.ceremony_number,
  c.film_year,
  c.year_start,
  cat.class as award_class,
  cat.canonical_name,
  n.exact_category,
  n.winner,
  n.detail,
  n.note,
  n.citation,
  n.citation_name,
  (
    select string_agg(nf.billed_title, ' / ' order by nf.position)
    from nomination_films nf
    where nf.nomination_id = n.id
  ) as films,
  (
    select string_agg(ne.billed_name, ', ' order by ne.position)
    from nomination_entities ne
    where ne.nomination_id = n.id
  ) as nominees
from nominations n
join ceremonies c on c.number = n.ceremony_number
join categories cat on cat.id = n.category_id;
